def solve_case(case):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in case['s']:
        if char in '([{':
            stack.append(char)
        elif not stack or stack.pop() != pairs[char]:
            return False
    return not stack

def solve_case(case):
    grid = case['grid']
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] or grid[rows - 1][cols - 1]:
        return -1
    queue = [(0, 0, 0)]
    seen = {(0, 0)}
    head = 0
    while head < len(queue):
        row, col, dist = queue[head]
        head += 1
        if row == rows - 1 and col == cols - 1:
            return dist
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and not grid[nr][nc] and (nr, nc) not in seen:
                seen.add((nr, nc))
                queue.append((nr, nc, dist + 1))
    return -1

def solve_case(case):
    tails = []
    for value in case['nums']:
        left, right = 0, len(tails)
        while left < right:
            middle = (left + right) // 2
            if tails[middle] < value:
                left = middle + 1
            else:
                right = middle
        if left == len(tails):
            tails.append(value)
        else:
            tails[left] = value
    return len(tails)
